    n = len(parent)
    children = [[] for _ in range(n)]
    root = 0
    for i, p in enumerate(parent):
        if p < 0:
            root = i
        else:
            children[p].append(i)
    order = [root]
    for node in order:
        order.extend(children[node])
    down = [0] * n
    best = None
    for node in reversed(order):
        top1 = top2 = 0
        for child in children[node]:
            gain = down[child]
            if gain > top1:
                top1, top2 = gain, top1
            elif gain > top2:
                top2 = gain
        down[node] = values[node] + top1
        here = values[node] + top1 + top2
        if best is None or here > best:
            best = here
    return best

